import React, { useState } from "react";
import './ResetPassword.css';

const ResetPassword = () => {
    const [message, setMessage] = useState("");
    const [error, setError] = useState("");
    const [loading, setLoading] = useState(false);
    const [email, setEmail] = useState("")

    const handleSubmit = async (e) => {
        e.preventDefault();
    
        try {

          setLoading(false);
          setMessage("Ваш пароль изменён и отправлен Вам на почту.");
          setError("");
        } catch (err) {
          setLoading(false);
          setError(err.response?.data?.detail || "Произошла ошибка");
          setMessage("");
        }
      };
    return (
        <div class="main">
            <title>Сброс пароля</title>
            <header class="main_box">
                <a class="name" href="/">Сайт с олимпиадами</a>
                <a class="enter" href="/enter">Вход/Регистрация</a>
                <a class="search" href="/search" style={{float : "right"}}><span>Поиск по фильтрам</span></a> 
            </header>
            <h1>Сброс пароля</h1>
            <form onSubmit={handleSubmit} class="change_password">
                <label>Email:</label>
                <input type="email" name="email" value={email} onChange={setEmail} required/>
                <button type="submit" class="search" disabled={loading || message || error}><span>Сбросить пароль</span></button>
            </form>
            {loading && <p>Загрузка...</p>}
            {message && <p style={{ color: "green" }}>{message}</p>}
            {error && <p style={{ color: "red" }}>{error}</p>}
            <footer>Сайт с олимпиадами 2025. Часть материалов была взята с сайта <a href="https://olimpiada.ru/" target="_blank">© Олимпиада.ру</a></footer>
        </div>
    )
}
export default ResetPassword
